/*
 * Shadid Heat and Air — site behaviour
 *  1. Mobile menu + services submenu
 *  2. Call tracking: dynamic number insertion by traffic source (or CallRail)
 *  3. Analytics: GA4 / Google Ads events for calls, texts and leads
 *  4. Lead forms: validation, attribution, POST to CRM webhook
 * Settings come from window.SITE_CONFIG (generated by build.js).
 */
(function () {
  "use strict";
  var cfg = window.SITE_CONFIG || {};
  var store = {
    get: function (k) { try { return JSON.parse(localStorage.getItem(k)); } catch (e) { return null; } },
    set: function (k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} }
  };
  var params = new URLSearchParams(location.search);

  /* ---------- 1. Menu ---------- */
  var body = document.body;
  var menuBtn = document.querySelector("[data-menu-btn]");
  if (menuBtn) {
    menuBtn.addEventListener("click", function () {
      var open = !body.classList.contains("menu-open");
      body.classList.toggle("menu-open", open);
      menuBtn.setAttribute("aria-expanded", String(open));
    });
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && body.classList.contains("menu-open")) {
        body.classList.remove("menu-open");
        menuBtn.setAttribute("aria-expanded", "false");
        menuBtn.focus();
      }
    });
  }
  document.querySelectorAll(".sub-toggle").forEach(function (btn) {
    btn.addEventListener("click", function () {
      var li = btn.closest(".has-sub");
      var open = !li.classList.contains("is-open");
      li.classList.toggle("is-open", open);
      btn.setAttribute("aria-expanded", String(open));
    });
  });
  var header = document.querySelector("[data-header]");
  if (header) {
    var onScroll = function () { header.classList.toggle("is-scrolled", window.scrollY > 8); };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
  }

  /* ---------- 2. Attribution + call tracking ---------- */
  // Last non-direct touch, kept 30 days.
  var ATTR_KEY = "sha_attr_v1";
  var DAY = 864e5;
  var touch = null;
  var utm = {};
  ["utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "gclid", "fbclid", "msclkid"].forEach(function (k) {
    if (params.get(k)) utm[k] = params.get(k);
  });
  var ref = document.referrer && document.referrer.indexOf(location.host) === -1 ? document.referrer : "";
  if (Object.keys(utm).length || ref) {
    var src = utm.utm_source ? utm.utm_source.toLowerCase() : "";
    var med = (utm.utm_medium || "").toLowerCase();
    var channel =
      utm.gclid || (src === "google" && /cpc|ppc|paid/.test(med)) ? "googleAds" :
      src === "gbp" || src === "gmb" || src === "google_business" ? "googleBusiness" :
      utm.fbclid || /facebook|fb|instagram|meta/.test(src) ? "facebook" :
      src ? "other" :
      /google\.|bing\.|yahoo\.|duckduckgo\./.test(ref) ? "organic" : "referral";
    touch = Object.assign({ channel: channel, landing: location.pathname, referrer: ref, at: Date.now() }, utm);
    store.set(ATTR_KEY, touch);
  } else {
    touch = store.get(ATTR_KEY);
    if (touch && Date.now() - touch.at > 30 * DAY) touch = null;
  }
  var channel = touch ? touch.channel : "direct";

  function digits(n) { return String(n || "").replace(/[^\d+]/g, ""); }
  function pretty(n) {
    var d = digits(n).replace(/^\+?1/, "");
    return d.length === 10 ? "(" + d.slice(0, 3) + ") " + d.slice(3, 6) + "-" + d.slice(6) : n;
  }
  var shownNumber = cfg.phone;
  if (cfg.callRailScript) {
    var s = document.createElement("script");
    s.src = cfg.callRailScript; s.async = true;
    document.head.appendChild(s);
  } else {
    var tn = (cfg.trackingNumbers || {})[channel];
    if (tn) {
      shownNumber = pretty(tn);
      var href = "+1" + digits(tn).replace(/^\+?1/, "");
      document.querySelectorAll("[data-phone-link]").forEach(function (a) { a.setAttribute("href", "tel:" + href); });
      document.querySelectorAll("[data-phone-text]").forEach(function (el) { el.textContent = shownNumber; });
    }
  }

  /* ---------- 3. Analytics ---------- */
  window.dataLayer = window.dataLayer || [];
  function gtag() { window.dataLayer.push(arguments); }
  window.gtag = window.gtag || gtag;
  var tagId = cfg.ga4Id || cfg.googleAdsId;
  if (tagId) {
    var g = document.createElement("script");
    g.async = true;
    g.src = "https://www.googletagmanager.com/gtag/js?id=" + encodeURIComponent(tagId);
    document.head.appendChild(g);
    window.gtag("js", new Date());
    if (cfg.ga4Id) window.gtag("config", cfg.ga4Id);
    if (cfg.googleAdsId) window.gtag("config", cfg.googleAdsId);
  }
  function track(event, data) {
    var payload = Object.assign({ page: location.pathname, channel: channel }, data || {});
    window.dataLayer.push(Object.assign({ event: event }, payload));
    if (tagId) window.gtag("event", event, payload);
  }
  document.addEventListener("click", function (e) {
    var a = e.target.closest("[data-track]");
    if (!a) return;
    var kind = a.getAttribute("data-track");
    if (kind === "call") track("phone_call_click", { number: shownNumber, placement: placement(a) });
    if (kind === "sms") track("sms_click", { placement: placement(a) });
  });
  function placement(el) {
    if (el.closest(".callbar")) return "mobile_bar";
    if (el.closest(".site-header")) return "header";
    if (el.closest(".site-footer")) return "footer";
    if (el.closest(".hero, .page-hero")) return "hero";
    return "content";
  }

  /* ---------- 4. Lead forms ---------- */
  var RULES = {
    name: function (v) { return v.trim().length < 2 ? "Enter your name." : ""; },
    phone: function (v) { return digits(v).replace(/^\+?1/, "").length !== 10 ? "Enter a 10-digit phone number, e.g. 405-555-0123." : ""; },
    service: function (v) { return !v ? "Choose the service you need (or “Not sure”)." : ""; },
    zip: function (v) { return !/^\d{5}$/.test(v.trim()) ? "Enter your 5-digit ZIP code." : ""; },
    email: function (v) { return v && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim()) ? "Enter a valid email like name@example.com, or leave it blank." : ""; },
    preferredDate: function (v) {
      if (!v) return "";
      var today = new Date(); today.setHours(0, 0, 0, 0);
      return new Date(v + "T00:00:00") < today ? "Choose today or a future date." : "";
    }
  };
  var LABELS = { name: "Name", phone: "Phone", service: "Service needed", zip: "ZIP code", email: "Email", preferredDate: "Preferred day" };

  function fieldWrap(input) { return input.closest(".field"); }
  function setError(input, msg) {
    var wrap = fieldWrap(input);
    var err = wrap && wrap.querySelector(".error");
    if (!err) return;
    wrap.classList.toggle("is-invalid", !!msg);
    input.setAttribute("aria-invalid", msg ? "true" : "false");
    err.textContent = msg;
    err.hidden = !msg;
  }
  function validate(input) {
    var rule = RULES[input.name];
    if (!rule || input.closest("[hidden]")) return "";
    var msg = rule(input.value || "");
    setError(input, msg);
    return msg;
  }

  document.querySelectorAll("[data-lead-form]").forEach(function (form) {
    var started = false;
    // Booking toggle
    var toggle = form.querySelector("[data-request-toggle]");
    var bookingBox = form.querySelector("[data-booking-only]");
    var submitLabel = form.querySelector(".btn__label");
    function syncType() {
      var checked = form.querySelector('input[name="requestType"]:checked');
      var booking = checked && checked.value === "Service visit";
      if (bookingBox) bookingBox.hidden = !booking;
      if (submitLabel && toggle) submitLabel.textContent = booking ? "Request my appointment" : "Get my free estimate";
    }
    if (toggle) {
      toggle.addEventListener("change", syncType);
      if (params.get("type") === "booking") {
        var r = form.querySelector('input[name="requestType"][value="Service visit"]');
        if (r) r.checked = true;
      }
      syncType();
    }
    // Pre-fill service from ?service=
    var svcParam = params.get("service");
    var svc = form.querySelector('select[name="service"]');
    if (svcParam && svc) {
      Array.prototype.forEach.call(svc.options, function (o) { if (o.text.toLowerCase() === svcParam.toLowerCase()) svc.value = o.value || o.text; });
    }
    var dateInput = form.querySelector('input[name="preferredDate"]');
    if (dateInput) dateInput.min = new Date(Date.now() - new Date().getTimezoneOffset() * 6e4).toISOString().slice(0, 10);

    form.addEventListener("focusin", function () {
      if (!started) { started = true; track("form_start", { form: form.classList.contains("lead-form--compact") ? "quick" : "full" }); }
    });
    form.addEventListener("focusout", function (e) {
      if (e.target.name && RULES[e.target.name] && e.target.value) validate(e.target);
    });
    form.addEventListener("input", function (e) {
      var wrap = e.target.closest && e.target.closest(".field.is-invalid");
      if (wrap) validate(e.target);
    });

    form.addEventListener("submit", function (e) {
      e.preventDefault();
      var summary = form.querySelector(".form-summary");
      var problems = [];
      Array.prototype.forEach.call(form.elements, function (el) {
        if (!el.name || !RULES[el.name]) return;
        var msg = validate(el);
        if (msg) problems.push({ el: el, msg: msg });
      });
      if (problems.length) {
        if (problems.length > 1 && summary) {
          summary.innerHTML = "Please fix " + problems.length + " things:<ul>" + problems.map(function (p) {
            return '<li><a href="#' + p.el.id + '">' + LABELS[p.el.name] + "</a></li>";
          }).join("") + "</ul>";
          summary.hidden = false;
          summary.focus();
        } else {
          if (summary) summary.hidden = true;
          problems[0].el.focus();
        }
        return;
      }
      if (summary) summary.hidden = true;
      if (form.company_website && form.company_website.value) return; // bot

      var data = {};
      new FormData(form).forEach(function (v, k) { if (k !== "company_website") data[k] = typeof v === "string" ? v.trim() : v; });
      data.smsConsent = data.smsConsent === "yes";
      var lead = Object.assign(data, {
        source: "Website",
        form: form.classList.contains("lead-form--compact") ? "Quick estimate" : "Contact page",
        page: location.pathname,
        pageTitle: document.title,
        submittedAt: new Date().toISOString(),
        channel: channel,
        trackingNumberShown: shownNumber,
        landingPage: touch ? touch.landing : location.pathname,
        referrer: touch ? touch.referrer : document.referrer
      }, touch ? {
        utm_source: touch.utm_source || "", utm_medium: touch.utm_medium || "", utm_campaign: touch.utm_campaign || "",
        utm_term: touch.utm_term || "", utm_content: touch.utm_content || "", gclid: touch.gclid || "", fbclid: touch.fbclid || ""
      } : {});

      var btn = form.querySelector('button[type="submit"]');
      var oldHTML = btn.innerHTML;
      btn.disabled = true;
      btn.innerHTML = '<span class="spinner" aria-hidden="true"></span><span>Sending…</span>';

      send(lead).then(function (demo) {
        track("generate_lead", { request_type: lead.requestType, service: lead.service });
        if (cfg.googleAdsId && cfg.googleAdsLeadLabel) window.gtag("event", "conversion", { send_to: cfg.googleAdsId + "/" + cfg.googleAdsLeadLabel });
        store.set("sha_last_lead", { name: lead.name, type: lead.requestType, demo: demo });
        location.href = "thank-you.html" + (lead.requestType === "Service visit" ? "?type=booking" : "");
      }).catch(function () {
        btn.disabled = false;
        btn.innerHTML = oldHTML;
        if (summary) {
          summary.innerHTML = "We couldn't send your request — please try again, or call us at <a href=\"tel:" + digits(shownNumber) + "\">" + shownNumber + "</a>.";
          summary.hidden = false;
          summary.focus();
        }
      });
    });
  });

  // POST to the CRM webhook (and optional email endpoint). Resolves true in demo mode.
  function send(lead) {
    var targets = [cfg.crmWebhook, cfg.emailEndpoint].filter(Boolean);
    if (!targets.length) {
      var queue = store.get("sha_demo_leads") || [];
      queue.unshift(lead);
      store.set("sha_demo_leads", queue.slice(0, 50));
      console.warn("[leads] No crmWebhook set in build.js — lead saved in this browser only (demo mode):", lead);
      return new Promise(function (r) { setTimeout(function () { r(true); }, 500); });
    }
    return Promise.all(targets.map(function (url, i) {
      return fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json" },
        body: JSON.stringify(lead)
      }).then(function (res) {
        if (!res.ok && i === 0) throw new Error("HTTP " + res.status);
      });
    })).then(function () { return false; });
  }

  /* ---------- Thank-you page ---------- */
  var ty = document.querySelector("[data-thanks]");
  if (ty) {
    var last = store.get("sha_last_lead");
    if (last && last.name) {
      var first = String(last.name).split(" ")[0];
      var h = ty.querySelector("[data-thanks-name]");
      if (h) h.textContent = "Thanks, " + first + "!";
    }
    if (params.get("type") === "booking") {
      var m = ty.querySelector("[data-thanks-msg]");
      if (m) m.textContent = "We got your appointment request. We'll call or text shortly to confirm your arrival window.";
    }
    if (last && last.demo && /localhost|127\.0\.0\.1/.test(location.hostname)) {
      var n = document.createElement("p");
      n.className = "demo-note";
      n.textContent = "Demo mode: no CRM webhook is set in build.js, so this request was saved in this browser only.";
      ty.appendChild(n);
    }
  }

  /* ---------- Reveal on scroll ---------- */
  if ("IntersectionObserver" in window && !matchMedia("(prefers-reduced-motion: reduce)").matches) {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) { if (en.isIntersecting) { en.target.classList.add("is-in"); io.unobserve(en.target); } });
    }, { rootMargin: "0px 0px -8% 0px" });
    document.querySelectorAll(".svc-card, .review-card, .trust-card, .step, .area-card, .gallery figure").forEach(function (el) {
      el.classList.add("reveal");
      io.observe(el);
    });
  }
})();
